class Solution:
    def maxCoins(self, nums: List[int]) -> int:
        a = [1] + nums + [1]
        n = len(a)
        dp = [[0] * n for _ in range(n)]

        for length in range(2, n):
            for left in range(n - length):
                right = left + length
                best = 0
                for k in range(left + 1, right):
                    best = max(
                        best,
                        dp[left][k] + a[left] * a[k] * a[right] + dp[k][right]
                    )
                dp[left][right] = best

        return dp[0][n - 1]

