int maxCoins(int* nums, int numsSize) {
    int a[302];
    int dp[302][302] = {{0}};

    a[0] = 1;
    for (int i = 0; i < numsSize; ++i) a[i + 1] = nums[i];
    a[numsSize + 1] = 1;

    int total = numsSize + 2;
    for (int length = 2; length < total; ++length) {
        for (int left = 0; left + length < total; ++left) {
            int right = left + length;
            int best = 0;
            for (int k = left + 1; k < right; ++k) {
                int value = dp[left][k]
                          + a[left] * a[k] * a[right]
                          + dp[k][right];
                if (value > best) best = value;
            }
            dp[left][right] = best;
        }
    }

    return dp[0][total - 1];
}

