static vector<int> parseArray(const string& line) {
    size_t first = line.find('[');
    size_t second = line.find('[', first + 1);
    size_t last = line.rfind(']');
    vector<int> nums;

    if (second == string::npos || last == string::npos || last <= second) return nums;

    string body = line.substr(second + 1, last - second - 1);
    stringstream ss(body);
    string part;

    while (getline(ss, part, ',')) {
        if (!part.empty()) nums.push_back(stoi(part));
    }
    return nums;
}

