public class Main {
    static List<Integer> parseArray(String s) {
        s = s.trim();
        int first = s.indexOf('[');
        int second = s.indexOf('[', first + 1);
        int last = s.lastIndexOf(']');
        if (second == -1 || last <= second) return new ArrayList<>();
        if (last > 0 && s.charAt(last - 1) == ']') last--;

        String body = s.substring(second + 1, last);
        List<Integer> values = new ArrayList<>();
        if (body.trim().isEmpty()) return values;

        for (String part : body.split(",")) {
            values.add(Integer.parseInt(part.trim()));
        }
        return values;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        List<Integer> values = parseArray(line);
        int[] nums = new int[values.size()];
        for (int i = 0; i < values.size(); i++) nums[i] = values.get(i);

        System.out.println(new Solution().maxCoins(nums));
    }
}

